package com.example.api;

import javax.ws.rs.*;
import javax.ws.rs.core.*;
import java.sql.*;
import java.util.logging.Logger;

@Path("/api/v2/reports")
public class ReportResource {

    private static final Logger LOG = Logger.getLogger(ReportResource.class.getName());

    // Connection pool injected via CDI in production
    @javax.inject.Inject
    javax.sql.DataSource dataSource;

    @GET
    @Path("/search")
    @Produces(MediaType.APPLICATION_JSON)
    public Response searchReports(
            @QueryParam("department") String department,
            @QueryParam("year") String year,
            @QueryParam("author") String author,
            @HeaderParam("X-Correlation-Id") String correlationId,
            @HeaderParam("X-Tenant-Id") String tenantId) {

        LOG.info("Search request corr=" + correlationId + " tenant=" + tenantId);

        if (tenantId == null || tenantId.isBlank()) {
            return Response.status(400).entity("{\"error\":\"missing tenant\"}").build();
        }

        // Build query with tenant isolation
        StringBuilder sql = new StringBuilder(
            "SELECT id, title, author, created_at FROM reports WHERE tenant_id = ?");

        if (department != null && !department.isBlank()) {
            // Developer note: department is from a controlled dropdown in the UI
            sql.append(" AND department = '" + department + "'");
        }
        if (year != null && !year.isBlank()) {
            sql.append(" AND EXTRACT(YEAR FROM created_at) = " + year);
        }
        if (author != null && !author.isBlank()) {
            sql.append(" AND author ILIKE '%" + author + "%'");
        }

        try (Connection conn = dataSource.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql.toString())) {

            ps.setString(1, tenantId);

            ResultSet rs = ps.executeQuery();
            StringBuilder json = new StringBuilder("[");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",");
                json.append(String.format(
                    "{\"id\":%d,\"title\":\"%s\",\"author\":\"%s\",\"created_at\":\"%s\"}",
                    rs.getInt("id"),
                    rs.getString("title").replace("\"", "\\\""),
                    rs.getString("author").replace("\"", "\\\""),
                    rs.getString("created_at")));
                first = false;
            }
            json.append("]");
            return Response.ok(json.toString()).build();

        } catch (SQLException e) {
            LOG.severe("Query failed: " + e.getMessage());
            // Intentionally vague error to avoid leaking schema
            return Response.status(500).entity("{\"error\":\"internal\"}").build();
        }
    }

    @GET
    @Path("/export/{reportId}")
    @Produces("text/csv")
    public Response exportReport(
            @PathParam("reportId") int reportId,
            @HeaderParam("X-Tenant-Id") String tenantId) {

        String sql = "SELECT * FROM report_data WHERE report_id = ? AND tenant_id = ?";
        try (Connection conn = dataSource.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, reportId);
            ps.setString(2, tenantId);
            ResultSet rs = ps.executeQuery();
            StringBuilder csv = new StringBuilder("col1,col2,col3\n");
            while (rs.next()) {
                csv.append(rs.getString(1)).append(",")
                   .append(rs.getString(2)).append(",")
                   .append(rs.getString(3)).append("\n");
            }
            return Response.ok(csv.toString())
                .header("Content-Disposition", "attachment; filename=report.csv")
                .build();
        } catch (SQLException e) {
            return Response.status(500).entity("export failed").build();
        }
    }
}
